def _build_jp_cafe_sentences(spec: dict) -> list[tuple[str, None, str]]:
    if spec["id"] not in JP_CAFE_SENTENCES_BY_ID:
        raise ValueError(f"Missing Japanese cafe sentences: {spec['id']}")
    return [(target, None, translation) for target, translation in JP_CAFE_SENTENCES_BY_ID[spec["id"]]]


def _build_vocab_from_terms(
    terms: list[tuple[str, str]],
    sentences: list[tuple[str, None, str]],
) -> list[tuple[str, str, str, str]]:
    return [
        (term, term, meaning, sentences[index // 2][0])
        for index, (term, meaning) in enumerate(terms)
    ]


def _build_jp_cafe_courses() -> list[dict]:
    courses = []
    for spec in JP_CAFE_SPECS:
        sentences = _build_jp_cafe_sentences(spec)
        courses.append(
            {
                "id": spec["id"],
                "title": spec["title"],
                "level": spec["level"],
                "description": spec["description"],
                "estimated_minutes": spec["estimated_minutes"],
                "sentences": sentences,
                "vocabulary": _build_vocab_from_terms(spec["terms"], sentences),
            }
        )
    return courses


