def _build_jp_casual_courses() -> list[dict]:
    courses = []
    for spec in JP_CASUAL_CHAT_SPECS:
        sentences = [(target, None, translation) for target, translation, _first, _second in spec["lines"]]
        vocabulary = []
        for index, (target, _translation, first, second) in enumerate(spec["lines"]):
            vocabulary.append((first[0], first[0], first[1], target))
            vocabulary.append((second[0], second[0], second[1], target))
        courses.append(
            {
                "id": spec["id"],
                "title": spec["title"],
                "level": spec["level"],
                "description": spec["description"],
                "estimated_minutes": spec["estimated_minutes"],
                "sentences": sentences,
                "vocabulary": vocabulary,
            }
        )
    return courses


