def _scenario_id_from_course(course_id: str) -> str:
    return course_id.rsplit("-l", 1)[0]


for scenario in SCENARIOS:
    scenario_courses = [
        course
        for course in COURSE_BLUEPRINTS
        if _scenario_id_from_course(course["id"]) == scenario["id"]
    ]
    scenario["courses"] = [
        {
            "id": course["id"],
            "title": course["title"],
            "level": course["level"],
            "order_index": index,
            "description": course["description"],
            "estimated_minutes": course["estimated_minutes"],
        }
        for index, course in enumerate(scenario_courses, start=1)
    ]


