def _normalize_sentences(course: dict) -> list[tuple[str, str | None, str]]:
    normalized = []
    for sentence in course["sentences"]:
        if len(sentence) == 2:
            target, translation = sentence
            normalized.append((target, None, translation))
        else:
            target, reading, translation = sentence
            normalized.append((target, reading, translation))
    return normalized


def _extract_vocabulary(sentences: list[tuple[str, str | None, str]]) -> list[tuple[str, str, str, str]]:
    seen: OrderedDict[str, str] = OrderedDict()
    sentence_blob = " ".join(target.lower() for target, _reading, _translation in sentences)
    for phrase in GLOSSARY:
        if " " not in phrase or phrase not in sentence_blob:
            continue
        for target, _reading, _translation in sentences:
            if phrase in target.lower():
                seen[phrase] = target
                break

    for target, _reading, _translation in sentences:
        for raw in re.findall(r"[A-Za-z]+(?:-[A-Za-z]+)?", target):
            term = raw.lower()
            if term in STOPWORDS or term not in GLOSSARY or term in seen:
                continue
            seen[term] = target

    if len(seen) < 30:
        raise ValueError(f"Only extracted {len(seen)} vocabulary items from lesson: {sentences[0][0]}")

    return [(term, term, GLOSSARY[term], example) for term, example in list(seen.items())[:30]]


COURSE_CONTENT = {
    course["id"]: {
        "sentences": _normalize_sentences(course),
        "vocabulary": course.get("vocabulary") or _extract_vocabulary(_normalize_sentences(course)),
    }
    for course in COURSE_BLUEPRINTS
}
